    band = band_rows if horizontal else band_cols
    size = len(band)
    pitch = size + 1
    q = band[0] // pitch
    n = (h if horizontal else w) // pitch + 1

    # Remove the divider.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0

    def tile_at(i, j):
        r0, c0 = i * pitch, j * pitch
        return [[grid[r0 + a][c0 + b] for b in range(size)]
                for a in range(size)]

    # First nonempty tile is the pattern used to restore the hidden band.
    pattern = None
    for i in range(n):
        for j in range(n):
            if (horizontal and i == q) or (not horizontal and j == q):
                continue
            t = tile_at(i, j)
            if any(v == 2 for row in t for v in row):
                pattern = t
                break
        if pattern is not None:
            break

    # Mark the indexed cell in every existing tile.
    for i in range(n):
        for j in range(n):
            if (horizontal and i == q) or (not horizontal and j == q):
                continue
            r0, c0 = i * pitch, j * pitch
            t = tile_at(i, j)
            if i < size and j < size and t[i][j] == 2:
                out[r0 + i][c0 + j] = 8

    if pattern is not None:
        # The divider hides copies of the pattern at locations whose
        # corresponding indexed cell is occupied in the pattern.
        for i in range(n):
            for j in range(n):
                if horizontal:
                    if i != q or i >= size or j >= size or pattern[i][j] != 2:
                        continue
                else:
                    if j != q or i >= size or j >= size or pattern[i][j] != 2:
                        continue

                r0, c0 = i * pitch, j * pitch
                for a in range(size):
                    for b in range(size):
                        out[r0 + a][c0 + b] = pattern[a][b]
                out[r0 + i][c0 + j] = 8

    return out
